// withAuth — 6-step token acquisition per cross-cutting.auth.token_acquisition_flow.
// Lives in frontend/lib/auth.ts. Called by every authenticated route handler.
// STATELESS per-request: there is NO shared in-memory cache across requests.
//
// Inputs: NextRequest req, downstream(bearer) async function returning Response.
// Output: Response (with Set-Cookie when refresh fired).

async function withAuth(req, downstream) {
  // Step 1: read 'access' cookie (HttpOnly so JS cannot, but server can)
  let access = readCookie(req.headers.get('cookie'), 'access')

  // Step 2: if present and not within 30s of exp, forward immediately
  if (access) {
    const claims = decodeJwtNoVerify(access) // base64url-decode payload only
    if (Date.now()/1000 + 30 < claims.exp) {
      return downstream(access)              // happy path, NO refresh call
    }
  }

  // Step 3: missing or expired -> need refresh; refresh cookie required
  const refresh = readCookie(req.headers.get('cookie'), 'refresh')
  if (!refresh) {
    return envelope401('AUTH_MISSING', 'No session found. Please log in.')
  }

  // Step 4: call identity.refresh
  let refreshRes
  try {
    refreshRes = await fetch(`${BACKEND_IDENTITY_BASE_URL}/api/v1/identity/user/refresh`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ refreshToken: refresh })
    })
  } catch {
    return envelope502('UPSTREAM_TIMEOUT', 'Identity service unreachable')
  }
  const body = await refreshRes.json()

  // Step 6: revoked/invalid -> clear both cookies + 401 AUTH_REVOKED
  if (refreshRes.status === 401 || body.code === 'AUTH_REVOKED' || body.code === 'AUTH_INVALID') {
    return envelope401WithClearedCookies('AUTH_REVOKED', 'Session expired. Please log in again.')
  }
  if (body.code !== 'SUCCESS' || !body.data) {
    return envelope502('UPSTREAM_TIMEOUT', 'Unexpected identity response')
  }

  // Step 5: rotate both cookies, forward original request with new access
  const { accessToken, refreshToken } = body.data
  const downstreamRes = await downstream(accessToken)
  const headers = new Headers(downstreamRes.headers)
  headers.append('Set-Cookie', buildAccessCookie(accessToken))   // HttpOnly; SameSite=Lax; Secure (prod); Path=/; Max-Age=900
  headers.append('Set-Cookie', buildRefreshCookie(refreshToken)) // HttpOnly; SameSite=Lax; Secure (prod); Path=/; Max-Age=1209600
  return new Response(downstreamRes.body, { status: downstreamRes.status, headers })
}

function decodeJwtNoVerify(jwt) {
  // split('.'), base64url-decode payload, JSON.parse. NEVER attempts signature verify.
  // Verification authority remains the BACKEND middleware.
}

function buildAccessCookie(value) {
  const secure = process.env.NODE_ENV === 'production' ? ' Secure;' : ''
  return `access=${value}; Path=/; HttpOnly; SameSite=Lax;${secure} Max-Age=900`
}

function buildRefreshCookie(value) {
  const secure = process.env.NODE_ENV === 'production' ? ' Secure;' : ''
  return `refresh=${value}; Path=/; HttpOnly; SameSite=Lax;${secure} Max-Age=1209600`
}
